{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "DynamicToolCallParams",
  "type": "object",
  "required": [
    "arguments",
    "callId",
    "threadId",
    "tool",
    "turnId"
  ],
  "properties": {
    "arguments": true,
    "callId": {
      "type": "string"
    },
    "namespace": {
      "type": [
        "string",
