          "type": "object",
          "required": [
            "httpConnectionFailed"
          ],
          "properties": {
            "httpConnectionFailed": {
              "type": "object",
              "properties": {
                "httpStatusCode": {
                  "type": [
                    "integer",
                    "null"
                  ],
                  "format": "uint16",
                  "minimum": 0.0
                }
              }
            }
          },
          "additionalProperties": false,
          "title": "HttpConnectionFailedCodexErrorInfo"
